        "biography": "Purdue University 기계공학부 Betty Ruth & Milton B. Hollander Family Professor로 공식 인물 페이지에 기재. 절연성 FC-72 액체에 직접 담근 전자 열원의 비등과 액침 모듈 연구를 함께 제시할 수 있다. 유체를 바꿀 때에도 냉각 구조·비등 조건을 분리해서 검토해야 한다는 관점을 보강한다.",
